contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount, uint withdrawAmount) public payable {
        require(depositAmount > 0, "deposit must be positive");
        require(address(this).balance >= depositAmount, "insufficient balance");

        uint beforeTestBalance = address(this).balance;
        uint beforeContractBalance = address(c).balance;
        c.deposit{value: depositAmount}();

        // withdrawAll takes no arguments; withdrawAmount is unused but kept for interface uniformity
        (bool callResult, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        uint afterTestBalance = address(this).balance;
        uint afterContractBalance = address(c).balance;

        // General rule: withdrawAll must complete successfully and return exactly the deposited Ether
        // to the caller, leaving the contract's balance reduced by the deposit.
        assert(callResult && afterTestBalance == beforeTestBalance + depositAmount && afterContractBalance == beforeContractBalance - depositAmount);
    }

    receive() external payable {}
}

