contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(uint deposit1, uint deposit2) public payable {
        require(address(this).balance >= deposit1 + deposit2, "not enough balance");

        uint before = address(c).balance;

        // deposit for this contract
        if (deposit1 > 0) {
            c.deposit{value: deposit1}();
        }
        // simulate another depositor by depositing again (still counted as same msg.sender)
        if (deposit2 > 0) {
            c.deposit{value: deposit2}();
        }

        uint afterDeposits = address(c).balance;

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: after withdrawAll, contract balance cannot be less than
        // afterDeposits minus the caller's total credit.
        // Since both deposits are from this contract, the caller's credit is deposit1 + deposit2.
        // If no credit (both deposits zero), withdrawAll must revert; otherwise it must not revert.
        // Also, if it did not revert, the contract balance must not be less than afterDeposits - (deposit1 + deposit2).
        uint totalCredit = deposit1 + deposit2;
        bool hasCredit = totalCredit > 0;

        if (hasCredit) {
            assert(!reverted);
        } else {
            assert(reverted);
        }

        if (!reverted) {
            uint after = address(c).balance;
            assert(after + totalCredit >= afterDeposits);
        } else {
            // If reverted, the balance should be unchanged from afterDeposits.
            uint afterRevert = address(c).balance;
            assert(afterRevert == afterDeposits);
        }
    }
}

